/** Native ordinary-item actions, complete Forge veto dispatch, physical loot and released ESSENCE bytecode. */
@GameTestHolder("thaumcraft") @PrefixGameTestTemplate(false)
public final class InfusionEnchantmentEffectsGameTests {
    private static final AtomicInteger ARENAS = new AtomicInteger();
    private static final TicketType<ChunkPos> NATIVE_TICKS=TicketType.create("thaumcraft_infusion_effects_qa",Comparator.comparingLong(ChunkPos::toLong));
    private InfusionEnchantmentEffectsGameTests() {}
    private static final class Wire extends Connection {
        final List<Packet<?>> packets = new ArrayList<>();
        Wire(){super(PacketFlow.SERVERBOUND);}
        @Override public void send(Packet<?> packet){packets.add(packet);}
        @Override public void send(Packet<?> packet, PacketSendListener listener){packets.add(packet);}
    }
    private static final class Trial implements AutoCloseable {
        final GameTestHelper h; final ServerLevel level; final BlockPos pos; final ServerPlayer p; final Wire wire;
        final Map<BlockPos,BlockState> before = new LinkedHashMap<>(); final List<Entity> owned = new ArrayList<>(); final List<Runnable> cleanup = new ArrayList<>(); boolean ticket,closed;
        Trial(GameTestHelper h){this.h=h;level=h.getLevel();pos=new BlockPos(9_000_008+64*ARENAS.incrementAndGet(),250,9_000_008);for(int x=-1;x<=1;x++)for(int z=-1;z<=1;z++)level.getChunkAt(pos.offset(16*x,0,16*z));p=new ServerPlayer(level.getServer(),level,new GameProfile(UUID.randomUUID(),"TC6Enchant"));wire=new Wire();p.connection=new ServerGamePacketListenerImpl(level.getServer(),wire,p);p.setPos(pos.getX()+.5,pos.getY(),pos.getZ()-2.5);p.setGameMode(GameType.SURVIVAL);p.setYRot(0);p.setXRot(0);}
        void put(BlockPos at,BlockState state){before.putIfAbsent(at.immutable(),level.getBlockState(at));level.setBlockAndUpdate(at,state);}
        ItemStack held(Item item,EnumInfusionEnchantment enchant,int rank){ItemStack stack=new ItemStack(item);EnumInfusionEnchantment.addInfusionEnchantment(stack,enchant,rank);p.setItemInHand(InteractionHand.MAIN_HAND,stack);return stack;}
        void plane(BlockState state){for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)put(pos.offset(x,y,0),state);}
        int air(){int n=0;for(int x=-1;x<=1;x++)for(int y=-1;y<=1;y++)if(level.isEmptyBlock(pos.offset(x,y,0)))n++;return n;}
        List<ItemEntity> drops(){return level.getEntitiesOfClass(ItemEntity.class,new AABB(pos).inflate(12));}
        int count(Item item){return drops().stream().filter(e->e.getItem().is(item)).mapToInt(e->e.getItem().getCount()).sum();}
        Cow cow(BlockPos at){Cow c=EntityType.COW.create(level);if(c==null)throw new AssertionError("Native cow missing");c.setPos(at.getX()+.5,at.getY(),at.getZ()+.5);c.setNoAi(true);c.setNoGravity(true);c.getAttribute(Attributes.MAX_HEALTH).setBaseValue(100);c.setHealth(100);level.addFreshEntity(c);owned.add(c);return c;}
        void use(InteractionHand hand){var hit=new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false);p.gameMode.useItemOn(p,level,p.getItemInHand(hand),hand,hit);}
        void roof(){for(int x=-8;x<=8;x++)for(int z=-8;z<=8;z++)put(pos.offset(x,2,z),Blocks.STONE.defaultBlockState());}
        void nativeTicks(){var chunk=new ChunkPos(pos);level.getChunkSource().addRegionTicket(NATIVE_TICKS,chunk,2,chunk);ticket=true;h.runAtTickTime(235,()->{if(!closed){close();h.fail("Owned Lamplight arena readiness/action exceeded its native tick bound");}});}
        void ready(boolean dark){var chunk=new ChunkPos(pos);h.assertTrue(level.areEntitiesLoaded(chunk.toLong())&&level.getChunkSource().isPositionTicking(chunk.toLong()),"Native lamp arena is not yet entity/block ticking");int above=level.getRawBrightness(pos.above(),0);h.assertTrue(dark?above<10:above>=10,"Native "+(dark?"roof":"sky")+" lighting is not yet ready: above="+above);if(!dark)h.assertTrue(level.getRawBrightness(pos,0)<10,"Original opaque target lighting has not yet settled");}
        List<ClientboundCustomPayloadPacket> sounding(){return wire.packets.stream().filter(q->q instanceof ClientboundCustomPayloadPacket).map(q->(ClientboundCustomPayloadPacket)q).filter(q->q.getIdentifier().equals(ResourceLocation.fromNamespaceAndPath("thaumcraft","tools"))).toList();}
        @Override public void close(){if(closed)return;closed=true;try{cleanup.forEach(Runnable::run);for(var row:before.entrySet())level.setBlockAndUpdate(row.getKey(),row.getValue());drops().forEach(Entity::discard);level.getEntitiesOfClass(ExperienceOrb.class,new AABB(pos).inflate(12)).forEach(Entity::discard);owned.forEach(Entity::discard);MinecraftForge.EVENT_BUS.post(new PlayerEvent.PlayerLoggedOutEvent(p));}finally{if(ticket){var chunk=new ChunkPos(pos);level.getChunkSource().removeRegionTicket(NATIVE_TICKS,chunk,2,chunk);}}}
    }
    private static void run(GameTestHelper h,Consumer<Trial> body){try(var f=new Trial(h)){body.accept(f);}h.succeed();}

    @GameTest(template="empty") public static void ordinaryDiamondPickUsesNativeDefaultHookForNinePaidDestructiveBlocks(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var tool=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.DESTRUCTIVE,1);int[] events={0};Consumer<BlockEvent.BreakEvent> listener=e->{if(e.getPlayer()==f.p)events[0]++;};MinecraftForge.EVENT_BUS.addListener(listener);try{h.assertTrue(!f.p.gameMode.destroyBlock(f.pos),"Infused vanilla item fell through to second harvest");}finally{MinecraftForge.EVENT_BUS.unregister(listener);}h.assertTrue(f.air()==9&&f.count(Items.COBBLESTONE)==9&&tool.getDamageValue()==9&&events[0]==9,"Default hook absent, duplicate central event, or physical payment/loot mismatch");});}
    @GameTest(template="empty") public static void ordinaryIronShovelDestructiveUsesShovelEffectivePlane(GameTestHelper h){run(h,f->{f.plane(Blocks.DIRT.defaultBlockState());var tool=f.held(Items.IRON_SHOVEL,EnumInfusionEnchantment.DESTRUCTIVE,1);f.p.gameMode.destroyBlock(f.pos);h.assertTrue(f.air()==9&&f.count(Items.DIRT)==9&&tool.getDamageValue()==9,"Vanilla shovel destructive did not remove/pay its nine dirt blocks");});}
    @GameTest(template="empty") public static void ordinaryIronAxeDestructiveUsesAxeEffectivePlane(GameTestHelper h){run(h,f->{f.plane(Blocks.OAK_PLANKS.defaultBlockState());var tool=f.held(Items.IRON_AXE,EnumInfusionEnchantment.DESTRUCTIVE,1);f.p.gameMode.destroyBlock(f.pos);h.assertTrue(f.air()==9&&f.count(Items.OAK_PLANKS)==9&&tool.getDamageValue()==9,"Vanilla axe destructive did not remove/pay its nine wooden blocks");});}
    @GameTest(template="empty") public static void uninfusedVanillaDefaultHookRemainsSingleOrdinaryHarvest(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var tool=new ItemStack(Items.DIAMOND_PICKAXE);f.p.setItemInHand(InteractionHand.MAIN_HAND,tool);h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&f.air()==1&&f.count(Items.COBBLESTONE)==1&&tool.getDamageValue()==1&&!tool.getOrCreateTag().contains("infench"),"Uninfused cold path changed native vanilla action");});}
    @GameTest(template="empty") public static void lowestPriorityLateCentralVetoPreventsAllOrdinaryToolEffects(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var tool=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.DESTRUCTIVE,1);int[] calls={0};Consumer<BlockEvent.BreakEvent> veto=e->{if(e.getPlayer()==f.p){calls[0]++;e.setCanceled(true);}};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,veto);try{h.assertTrue(!f.p.gameMode.destroyBlock(f.pos),"Late veto did not stop native action");}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(f.air()==0&&f.drops().isEmpty()&&tool.getDamageValue()==0&&calls[0]==1,"Default hook mutated before final central protection veto");});}
    @GameTest(template="empty") public static void finalLateLowestNativeOreExperienceIsPaidExactlyOnce(GameTestHelper h){run(h,f->{f.put(f.pos,Blocks.COAL_ORE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.COLLECTOR,1);int[] calls={0};Consumer<BlockEvent.BreakEvent> listener=e->{if(e.getPlayer()==f.p){calls[0]++;e.setExpToDrop(11);}};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,listener);try{h.assertTrue(!f.p.gameMode.destroyBlock(f.pos),"Infused ordinary ore bypassed approved native hook");}finally{MinecraftForge.EVENT_BUS.unregister(listener);}int xp=f.level.getEntitiesOfClass(ExperienceOrb.class,new AABB(f.pos).inflate(12)).stream().mapToInt(ExperienceOrb::getValue).sum();h.assertTrue(calls[0]==1&&xp==11&&f.count(Items.COAL)==1&&pick.getDamageValue()==1,"Late native XP mutation was stale, duplicated or lost: events="+calls[0]+", XP="+xp);});}
    @GameTest(template="empty") public static void originalBurrowingOreSkipsExperienceButRetainsFarProtectionAndPhysicalLoot(GameTestHelper h){run(h,f->{for(int y=0;y<3;y++)f.put(f.pos.above(y),Blocks.COAL_ORE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.BURROWING,1);int[] calls={0};Consumer<BlockEvent.BreakEvent> listener=e->{if(e.getPlayer()==f.p){calls[0]++;e.setExpToDrop(11);}};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,listener);try{f.p.gameMode.destroyBlock(f.pos);}finally{MinecraftForge.EVENT_BUS.unregister(listener);}int xp=f.level.getEntitiesOfClass(ExperienceOrb.class,new AABB(f.pos).inflate(12)).stream().mapToInt(ExperienceOrb::getValue).sum();h.assertTrue(calls[0]==2&&xp==0&&f.level.getBlockState(f.pos).is(Blocks.COAL_ORE)&&f.level.isEmptyBlock(f.pos.above(2))&&f.count(Items.COAL)==1&&pick.getDamageValue()==1,"Released Burrowing zero-XP quirk or modern separate far approval was lost: events="+calls[0]+", XP="+xp);});}
    @GameTest(template="empty") public static void ordinaryDestructiveNeighborsHonorFullNativeVetoAndPreserveContainer(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());f.put(f.pos.east(),Blocks.CHEST.defaultBlockState());var chest=(net.minecraft.world.level.block.entity.ChestBlockEntity)f.level.getBlockEntity(f.pos.east());chest.setItem(0,new ItemStack(Items.DIAMOND,3));var tool=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.DESTRUCTIVE,1);int[] vetoes={0};Consumer<BlockEvent.BreakEvent> veto=e->{if(e.getPlayer()==f.p&&e.getPos().equals(f.pos.west())){vetoes[0]++;e.setCanceled(true);}};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,veto);try{f.p.gameMode.destroyBlock(f.pos);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(f.air()==7&&f.count(Items.COBBLESTONE)==7&&tool.getDamageValue()==7&&vetoes[0]==1&&f.level.getBlockEntity(f.pos.east())==chest&&chest.getItem(0).getCount()==3,"Protected neighbor/container was mined or billed");});}
    @GameTest(template="empty") public static void changedPhysicalToolDuringNeighborBreakCannotSpendReplacement(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var tool=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.DESTRUCTIVE,1);var replacement=new ItemStack(Items.DIAMOND_PICKAXE);Consumer<BlockEvent.BreakEvent> replace=e->{if(e.getPlayer()==f.p&&!e.getPos().equals(f.pos))f.p.setItemInHand(InteractionHand.MAIN_HAND,replacement);};MinecraftForge.EVENT_BUS.addListener(replace);try{f.p.gameMode.destroyBlock(f.pos);}finally{MinecraftForge.EVENT_BUS.unregister(replace);}h.assertTrue(f.air()==1&&f.count(Items.COBBLESTONE)==1&&tool.getDamageValue()==1&&replacement.getDamageValue()==0,"Neighbor callback spent detached tool or replacement");});}
    @GameTest(template="empty") public static void shiftDestructiveBypassAndIneffectiveStonePreserveOrdinaryMining(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var shovel=f.held(Items.DIAMOND_SHOVEL,EnumInfusionEnchantment.DESTRUCTIVE,1);h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&f.air()==1&&shovel.getDamageValue()==1,"Ineffective shovel triggered destructive extras");f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.DESTRUCTIVE,1);f.p.setShiftKeyDown(true);h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&f.air()==1&&pick.getDamageValue()==1,"Sneaking did not preserve single vanilla harvest");});}
    @GameTest(template="empty") public static void ordinaryBurrowingAxeHarvestsOneFarLogWithDistinctProtection(GameTestHelper h){run(h,f->{for(int y=0;y<5;y++)f.put(f.pos.above(y),Blocks.OAK_LOG.defaultBlockState());var axe=f.held(Items.IRON_AXE,EnumInfusionEnchantment.BURROWING,1);int[] clicked={0},far={0};Consumer<BlockEvent.BreakEvent> listener=e->{if(e.getPlayer()==f.p){if(e.getPos().equals(f.pos))clicked[0]++;if(e.getPos().equals(f.pos.above(4)))far[0]++;}};MinecraftForge.EVENT_BUS.addListener(listener);try{h.assertTrue(!f.p.gameMode.destroyBlock(f.pos),"Burrowing fell through to central vanilla harvest");}finally{MinecraftForge.EVENT_BUS.unregister(listener);}h.assertTrue(f.level.getBlockState(f.pos).is(Blocks.OAK_LOG)&&f.level.isEmptyBlock(f.pos.above(4))&&f.count(Items.OAK_LOG)==1&&axe.getDamageValue()==1&&clicked[0]==1&&far[0]==1,"Burrowing changed more than one physical far log or omitted approval");});}
    @GameTest(template="empty") public static void ordinaryBurrowingHonorsFarVetoAndShiftClickedLog(GameTestHelper h){run(h,f->{for(int y=0;y<4;y++)f.put(f.pos.above(y),Blocks.OAK_LOG.defaultBlockState());var axe=f.held(Items.DIAMOND_AXE,EnumInfusionEnchantment.BURROWING,1);Consumer<BlockEvent.BreakEvent> veto=e->{if(e.getPlayer()==f.p&&e.getPos().equals(f.pos.above(3)))e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,veto);try{f.p.gameMode.destroyBlock(f.pos);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(f.level.getBlockState(f.pos).is(Blocks.OAK_LOG)&&f.level.getBlockState(f.pos.above(3)).is(Blocks.OAK_LOG)&&axe.getDamageValue()==0&&f.drops().isEmpty(),"Far veto removed/billed any block");f.p.setShiftKeyDown(true);h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&f.level.isEmptyBlock(f.pos)&&f.level.getBlockState(f.pos.above(3)).is(Blocks.OAK_LOG)&&axe.getDamageValue()==1,"Sneaking burrowing did not use clicked native log");});}
    @GameTest(template="empty") public static void ordinaryOreBurrowingKeepsClickedOreAndPaysOneNativeDrop(GameTestHelper h){run(h,f->{for(int y=0;y<4;y++)f.put(f.pos.above(y),Blocks.IRON_ORE.defaultBlockState());var pick=f.held(Items.IRON_PICKAXE,EnumInfusionEnchantment.BURROWING,1);f.p.gameMode.destroyBlock(f.pos);h.assertTrue(f.level.getBlockState(f.pos).is(Blocks.IRON_ORE)&&f.level.isEmptyBlock(f.pos.above(3))&&f.count(Items.RAW_IRON)==1&&pick.getDamageValue()==1,"Vanilla ore-burrowing failed original one-far-block search");});}
    @GameTest(template="empty") public static void originalTcSubclassStillUsesOneDestructiveHarvestAndOneDurabilityPerBlock(GameTestHelper h){run(h,f->{f.plane(Blocks.STONE.defaultBlockState());var crusher=ToolItems.initializeStack(CatalogModule.stack("primal_crusher"));f.p.setItemInHand(InteractionHand.MAIN_HAND,crusher);f.p.gameMode.destroyBlock(f.pos);h.assertTrue(f.air()==9&&f.count(Items.COBBLESTONE)==9&&crusher.getDamageValue()==9,"Default hook double-called TC subclass custom action");});}
    @GameTest(template="empty") public static void ordinaryCollectorMarksActualPhysicalLootWithoutInventoryManufacture(GameTestHelper h){run(h,f->{f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.COLLECTOR,1);f.p.gameMode.destroyBlock(f.pos);var drops=f.drops();h.assertTrue(drops.size()==1&&drops.get(0).getItem().is(Items.COBBLESTONE)&&drops.get(0).noPhysics&&drops.get(0).isNoGravity()&&pick.getDamageValue()==1&&!f.p.getInventory().contains(new ItemStack(Items.COBBLESTONE)),"Collector failed physical homing or bypassed vanilla pickup");MinecraftForge.EVENT_BUS.post(new PlayerEvent.PlayerLoggedOutEvent(f.p));h.assertTrue(!drops.get(0).noPhysics&&!drops.get(0).isNoGravity(),"Collector logout did not restore original physical flags");});}
    @GameTest(template="empty") public static void ordinaryCollectorShiftLeavesNativeLootPhysics(GameTestHelper h){run(h,f->{f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.COLLECTOR,1);f.p.setShiftKeyDown(true);h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&f.count(Items.COBBLESTONE)==1&&pick.getDamageValue()==1&&f.drops().stream().noneMatch(e->e.noPhysics||e.isNoGravity()),"Sneaking collector did not bypass homing");});}
    @GameTest(template="empty") public static void vanillaSoundingBothHandsPayFiveOnceAndSendActualDimensionPosRank(GameTestHelper h){run(h,f->{f.put(f.pos,Blocks.STONE.defaultBlockState());var knowledge=KnowledgeStore.get(f.p).save();for(InteractionHand hand:InteractionHand.values()){f.p.getInventory().clearContent();var pick=new ItemStack(Items.IRON_PICKAXE);EnumInfusionEnchantment.addInfusionEnchantment(pick,EnumInfusionEnchantment.SOUNDING,4);f.p.setItemInHand(hand,pick);f.p.setShiftKeyDown(true);f.wire.packets.clear();f.use(hand);h.assertTrue(pick.getDamageValue()==5&&f.sounding().size()==1&&f.level.getBlockState(f.pos).is(Blocks.STONE),"Sounding did not pay once for actual "+hand);var data=new FriendlyByteBuf(f.sounding().get(0).getData().duplicate());h.assertTrue(data.readUnsignedByte()==0&&data.readResourceLocation().equals(f.level.dimension().location())&&data.readBlockPos().equals(f.pos)&&data.readUnsignedByte()==4&&!data.isReadable(),"SOUNDING packet did not retain authoritative target/rank");}h.assertTrue(knowledge.equals(KnowledgeStore.get(f.p).save()),"Sounding gave scan/research credits");});}
    @GameTest(template="empty") public static void soundingRequiresSneakingAndHonorsNativeUseVeto(GameTestHelper h){run(h,f->{f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.SOUNDING,2);f.use(InteractionHand.MAIN_HAND);h.assertTrue(pick.getDamageValue()==0&&f.sounding().isEmpty(),"Nonsneaking sounding acted");f.p.setShiftKeyDown(true);Consumer<PlayerInteractEvent.RightClickBlock> veto=e->{if(e.getEntity()==f.p)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(EventPriority.HIGHEST,veto);try{f.use(InteractionHand.MAIN_HAND);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(pick.getDamageValue()==0&&f.sounding().isEmpty(),"Canceled use paid or emitted sounding");});}
    @GameTest(template="empty") public static void ordinarySwordArcingUsesHalfActualEquippedDamageOnRankTargets(GameTestHelper h){run(h,f->{f.held(Items.IRON_SWORD,EnumInfusionEnchantment.ARCING,2);f.p.doTick();var primary=f.cow(f.pos);Cow a=f.cow(f.pos.east()),b=f.cow(f.pos.west()),c=f.cow(f.pos.south());float expected=(float)f.p.getAttributeValue(Attributes.ATTACK_DAMAGE)*.5F;f.p.attack(primary);h.assertTrue(primary.getHealth()<100&&List.of(a,b,c).stream().filter(e->e.getHealth()<100).count()==2,"Vanilla sword arcing did not hit exactly two additional mobs");for(var mob:List.of(a,b,c))if(mob.getHealth()<100)h.assertTrue(Math.abs(100-mob.getHealth()-expected)<.001,"Arcing did not use half equipped attack damage");});}
    @GameTest(template="empty") public static void ordinaryArcingHonorsNativeCanceledAttack(GameTestHelper h){run(h,f->{f.held(Items.DIAMOND_SWORD,EnumInfusionEnchantment.ARCING,4);Cow primary=f.cow(f.pos),other=f.cow(f.pos.east());Consumer<AttackEntityEvent> veto=e->{if(e.getEntity()==f.p)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(EventPriority.HIGHEST,veto);try{f.p.attack(primary);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(primary.getHealth()==100&&other.getHealth()==100,"Canceled actual attack produced arcing damage");});}
    @GameTest(template="empty") public static void essenceFiveMakesOnlyReleasedEntityTypedCrystalsAndCollectorMarksThem(GameTestHelper h){run(h,f->{var weapon=f.held(Items.IRON_SWORD,EnumInfusionEnchantment.ESSENCE,5);EnumInfusionEnchantment.addInfusionEnchantment(weapon,EnumInfusionEnchantment.COLLECTOR,1);var victim=f.cow(f.pos);AspectList source=AspectRegistry.getAspects(victim);var drops=new ArrayList<ItemEntity>();MinecraftForge.EVENT_BUS.post(new LivingDropsEvent(victim,f.p.damageSources().playerAttack(f.p),drops,0,true));h.assertTrue(drops.size()>=1&&drops.size()<=5&&weapon.getDamageValue()==0,"ESSENCE V failed guaranteed 1..5 original crystal range or invented durability");Map<Aspect,Integer> found=new HashMap<>();for(var drop:drops){var aspect=AspectCrystalItem.crystalAspect(drop.getItem());h.assertTrue(aspect!=null&&source.getAmount(aspect)>0&&drop.getItem().getCount()==1&&drop.noPhysics&&drop.isNoGravity()&&drop.getY()==victim.getY()+victim.getEyeHeight(),"Essence drop is untyped/not from victim/not physical eye-height homing");found.merge(aspect,1,Integer::sum);drop.discard();}found.forEach((aspect,n)->h.assertTrue(n<=source.getAmount(aspect),"Essence copied more aspect units than victim owns"));h.assertTrue(source.visSize()==AspectRegistry.getAspects(victim).visSize(),"Essence mutated global aspect definitions");});}
    @GameTest(template="empty") public static void essenceNativeKillEmitsRealTypedCrystalAlongsideOrdinaryDeathLoot(GameTestHelper h){run(h,f->{var weapon=f.held(Items.DIAMOND_SWORD,EnumInfusionEnchantment.ESSENCE,5);var victim=f.cow(f.pos);h.assertTrue(victim.hurt(f.p.damageSources().playerAttack(f.p),1000),"Native player-caused kill rejected");h.assertTrue(f.drops().stream().anyMatch(e->AspectCrystalItem.crystalAspect(e.getItem())!=null)&&f.drops().stream().anyMatch(e->e.getItem().is(Items.BEEF)||e.getItem().is(Items.LEATHER))&&weapon.getDamageValue()==0,"Real death pipeline omitted essence or ordinary loot");});}
    @GameTest(template="empty") public static void essenceDoesNotActForUnenchantedOffhandOrNonPlayerDamage(GameTestHelper h){run(h,f->{var victim=f.cow(f.pos);var off=new ItemStack(Items.DIAMOND_SWORD);EnumInfusionEnchantment.addInfusionEnchantment(off,EnumInfusionEnchantment.ESSENCE,5);f.p.setItemInHand(InteractionHand.OFF_HAND,off);var drops=new ArrayList<ItemEntity>();MinecraftForge.EVENT_BUS.post(new LivingDropsEvent(victim,f.p.damageSources().playerAttack(f.p),drops,0,true));h.assertTrue(drops.isEmpty(),"Offhand-only essence affected main-hand kill");f.p.setItemInHand(InteractionHand.MAIN_HAND,off);MinecraftForge.EVENT_BUS.post(new LivingDropsEvent(victim,f.level.damageSources().generic(),drops,0,true));h.assertTrue(drops.isEmpty(),"Nonplayer damage made essence crystals");});}
    @GameTest(template="empty") public static void canceledNativeLivingDropsCannotSpawnEssenceOrCollectorLoot(GameTestHelper h){run(h,f->{var weapon=f.held(Items.DIAMOND_SWORD,EnumInfusionEnchantment.ESSENCE,5);EnumInfusionEnchantment.addInfusionEnchantment(weapon,EnumInfusionEnchantment.COLLECTOR,1);var victim=f.cow(f.pos);Consumer<LivingDropsEvent> veto=e->{if(e.getEntity()==victim)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(EventPriority.HIGHEST,veto);try{victim.hurt(f.p.damageSources().playerAttack(f.p),1000);}finally{MinecraftForge.EVENT_BUS.unregister(veto);}h.assertTrue(f.drops().isEmpty(),"Canceled native death still emitted paid/essence loot");});}

    @GameTest(template="empty") public static void ordinaryRefiningPreservesNativeOreCountAndDoesNotReplaceEveryRoll(GameTestHelper h){run(h,f->{var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.REFINING,4);pick.enchant(Enchantments.SILK_TOUCH,1);f.level.random.setSeed(0xBE7A26L);var cluster=CatalogModule.stack("cluster_iron").getItem();int clusters=0,ores=0;for(int i=0;i<64;i++){f.put(f.pos,Blocks.IRON_ORE.defaultBlockState());h.assertTrue(!f.p.gameMode.destroyBlock(f.pos),"Refining vanilla pick skipped native default hook");clusters+=f.count(cluster);ores+=f.count(Items.IRON_ORE);f.drops().forEach(Entity::discard);}h.assertTrue(clusters>0&&ores>0&&clusters+ores==64&&pick.getDamageValue()==64,"Refining IV lost/duplicated physical ore count, ignored original chance, or added a cost: clusters="+clusters+", ores="+ores);});}
    @GameTest(template="empty") public static void refiningModernRawIronAndQuartzBecomeOriginalTypedClusters(GameTestHelper h){run(h,f->{var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.REFINING,4);f.level.random.setSeed(0x7A2604L);int iron=0,quartz=0;for(int i=0;i<32;i++){f.put(f.pos,Blocks.IRON_ORE.defaultBlockState());f.p.gameMode.destroyBlock(f.pos);iron+=f.count(CatalogModule.stack("cluster_iron").getItem());h.assertTrue(f.count(Items.RAW_IRON)+f.count(CatalogModule.stack("cluster_iron").getItem())==1,"Modern raw iron quantity changed through refining");f.drops().forEach(Entity::discard);f.put(f.pos,Blocks.NETHER_QUARTZ_ORE.defaultBlockState());f.p.gameMode.destroyBlock(f.pos);quartz+=f.count(CatalogModule.stack("cluster_quartz").getItem());h.assertTrue(f.count(Items.QUARTZ)+f.count(CatalogModule.stack("cluster_quartz").getItem())==1,"Original quartz quantity changed through refining");f.drops().forEach(Entity::discard);}h.assertTrue(iron>0&&quartz>0&&pick.getDamageValue()==64,"Refining skipped actual modern raw iron/original quartz or billed extra durability");});}
    @GameTest(template="empty") public static void releasedEssenceBytecodeAllowsFourOrFiveCrystalsAtRankFive(GameTestHelper h){run(h,f->{f.held(Items.DIAMOND_SWORD,EnumInfusionEnchantment.ESSENCE,5);var victim=f.cow(f.pos);f.level.random.setSeed(0xE55E040L);int largest=0;for(int i=0;i<64;i++){var drops=new ArrayList<ItemEntity>();MinecraftForge.EVENT_BUS.post(new LivingDropsEvent(victim,f.p.damageSources().playerAttack(f.p),drops,0,true));largest=Math.max(largest,drops.size());h.assertTrue(drops.size()>=1&&drops.size()<=5,"Essence V fell outside released range");drops.forEach(Entity::discard);}h.assertTrue(largest>=4,"Recovered-source unconditional for-step was used; released bytecode must permit four/five crystals");});}
    @GameTest(template="empty") public static void essencePlayerVictimRetainsNameSeededOriginalAspectPool(GameTestHelper h){run(h,f->{f.held(Items.DIAMOND_SWORD,EnumInfusionEnchantment.ESSENCE,5);var victim=new ServerPlayer(f.level.getServer(),f.level,new GameProfile(UUID.randomUUID(),"TC6EssenceName"));var expected=new AspectList().add(Aspect.MAN,4);var random=new Random("TC6EssenceName".hashCode());Aspect[] choices=Aspect.aspects.values().toArray(new Aspect[0]);for(int i=0;i<3;i++)expected.add(choices[random.nextInt(choices.length)],15);var drops=new ArrayList<ItemEntity>();MinecraftForge.EVENT_BUS.post(new LivingDropsEvent(victim,f.p.damageSources().playerAttack(f.p),drops,0,true));h.assertTrue(!drops.isEmpty(),"Player victim lost original special aspect route");for(var drop:drops){h.assertTrue(expected.getAmount(AspectCrystalItem.crystalAspect(drop.getItem()))>0,"Player essence did not come from original name-seeded pool");drop.discard();}});}

    @GameTest(template="empty",timeoutTicks=240) public static void nativeLamplightPlacesPersistentLightFifteenAfterPaidDarkHarvest(GameTestHelper h){var f=new Trial(h);f.nativeTicks();f.roof();f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.IRON_PICKAXE,EnumInfusionEnchantment.LAMPLIGHT,1);var knowledge=KnowledgeStore.get(f.p).save();h.startSequence().thenWaitUntil(()->f.ready(true)).thenExecute(()->{try{h.assertTrue(!f.p.gameMode.destroyBlock(f.pos)&&f.level.isEmptyBlock(f.pos)&&pick.getDamageValue()==1&&f.count(Items.COBBLESTONE)==1,"Lamplight did not first pay exactly one physical harvest");}catch(Throwable error){f.close();throw error;}}).thenIdle(3).thenExecute(()->{try{h.assertTrue(f.level.getBlockState(f.pos).is(CatalogBlocks.block("effect_glimmer")),"Native dark harvest lacks deferred glimmer: "+f.level.getBlockState(f.pos)+", raw="+f.level.getRawBrightness(f.pos,0));h.assertTrue(f.level.getBlockState(f.pos).getLightEmission(f.level,f.pos)==15&&pick.getDamageValue()==1&&knowledge.equals(KnowledgeStore.get(f.p).save()),"Deferred lamplight invented payment/research or lost light15");}finally{f.close();}}).thenSucceed();}
    @GameTest(template="empty",timeoutTicks=240) public static void lamplightRetainsRawSkyLightThresholdEvenAtNight(GameTestHelper h){var f=new Trial(h);f.nativeTicks();f.put(f.pos,Blocks.STONE.defaultBlockState());f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.LAMPLIGHT,1);h.startSequence().thenWaitUntil(()->f.ready(false)).thenExecute(()->{try{f.p.gameMode.destroyBlock(f.pos);}catch(Throwable error){f.close();throw error;}}).thenIdle(3).thenExecute(()->{try{h.assertTrue(f.level.isEmptyBlock(f.pos),"Lamplight used stale opaque/block-only light outdoors: "+f.level.getBlockState(f.pos)+", raw="+f.level.getRawBrightness(f.pos,0));h.assertTrue(f.count(Items.COBBLESTONE)==1,"Outdoor physical harvest loot changed: "+f.count(Items.COBBLESTONE));}finally{f.close();}}).thenSucceed();}
    @GameTest(template="empty",timeoutTicks=240) public static void lamplightShiftBypassDoesNotQueueAnyLight(GameTestHelper h){var f=new Trial(h);f.nativeTicks();f.roof();f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.LAMPLIGHT,1);f.p.setShiftKeyDown(true);h.startSequence().thenWaitUntil(()->f.ready(true)).thenExecute(()->{try{h.assertTrue(f.p.gameMode.destroyBlock(f.pos)&&pick.getDamageValue()==1,"Shift lamplight did not preserve ordinary single harvest");}catch(Throwable error){f.close();throw error;}}).thenIdle(3).thenExecute(()->{try{h.assertTrue(f.level.isEmptyBlock(f.pos),"Sneaking harvest queued a glimmer: "+f.level.getBlockState(f.pos));h.assertTrue(f.count(Items.COBBLESTONE)==1,"Sneaking ordinary physical loot changed: "+f.count(Items.COBBLESTONE));}finally{f.close();}}).thenSucceed();}
    @GameTest(template="empty",timeoutTicks=240) public static void lamplightNativePlacementVetoRestoresAirWithoutRefundingRealHarvest(GameTestHelper h){var f=new Trial(h);f.nativeTicks();f.roof();f.put(f.pos,Blocks.STONE.defaultBlockState());var pick=f.held(Items.DIAMOND_PICKAXE,EnumInfusionEnchantment.LAMPLIGHT,1);int[] calls={0};Consumer<BlockEvent.EntityPlaceEvent> veto=e->{if(e.getEntity()==f.p&&e.getPos().equals(f.pos)){calls[0]++;e.setCanceled(true);}};MinecraftForge.EVENT_BUS.addListener(EventPriority.LOWEST,veto);f.cleanup.add(()->MinecraftForge.EVENT_BUS.unregister(veto));h.startSequence().thenWaitUntil(()->f.ready(true)).thenExecute(()->{try{f.p.gameMode.destroyBlock(f.pos);}catch(Throwable error){MinecraftForge.EVENT_BUS.unregister(veto);f.close();throw error;}}).thenIdle(3).thenExecute(()->{try{h.assertTrue(calls[0]==1,"Native optional light placement callback count changed: "+calls[0]);h.assertTrue(f.level.isEmptyBlock(f.pos),"Vetoed optional light did not restore air: "+f.level.getBlockState(f.pos));h.assertTrue(f.count(Items.COBBLESTONE)==1&&pick.getDamageValue()==1,"Vetoed light changed physical harvest loot/durability: drops="+f.count(Items.COBBLESTONE)+", damage="+pick.getDamageValue());}finally{MinecraftForge.EVENT_BUS.unregister(veto);f.close();}}).thenSucceed();}
}
